// Validate Signed Request → Verify Authorization → Check Idempotency Key →
// Check Deadline. Rejects anything that is not a fresh, correctly signed
// request from Loopmend for an allowlisted action.
const crypto = require('crypto');
const item = $input.first().json;
const h = item.headers || {};
const req = item.body || {};
const raw = JSON.stringify(req); // Loopmend sends compact JSON.stringify output
const ts = String(h['x-loopmend-timestamp'] || '');
const nonce = String(h['x-loopmend-nonce'] || '');
const provided = String(h['x-loopmend-signature'] || '').replace(/^v1=/, '');
const expected = crypto.createHmac('sha256', $env.LOOPMEND_WEBHOOK_SECRET).update(`${ts}.${nonce}.${raw}`).digest('hex');
const reject = (status, message) => [{ json: { decision: 'reject', status, message } }];

if (!ts || !nonce || provided.length !== expected.length || !crypto.timingSafeEqual(Buffer.from(provided), Buffer.from(expected))) return reject(401, 'invalid signature');
if (Math.abs(Date.now() / 1000 - Number(ts)) > 300) return reject(401, 'stale request');
if (h['x-loopmend-integration'] !== $env.LOOPMEND_INTEGRATION_ID) return reject(401, 'unknown integration');
if (req.type !== 'recovery.execute') return reject(400, 'unsupported request');
const ALLOWED = ['retry_execution', 'exponential_backoff', 'refresh_credentials_then_retry', 'pause_workflow', 'notify_owner'];
if (!ALLOWED.includes(req.strategy)) return reject(422, `strategy ${req.strategy} is not allowlisted`);
if (new Date(req.deadline).getTime() < Date.now()) return reject(409, 'deadline exceeded');

// Idempotency: remember processed keys (workflow static data persists for active workflows).
const store = $getWorkflowStaticData('global');
store.processed = store.processed || {};
const prior = store.processed[req.idempotencyKey];
if (prior) return [{ json: { decision: 'duplicate', status: 200, result: prior } }];
const seenNonces = (store.nonces = store.nonces || {});
if (seenNonces[nonce]) return reject(409, 'replayed nonce');
seenNonces[nonce] = Date.now();
for (const [k, t] of Object.entries(seenNonces)) if (Date.now() - t > 3600_000) delete seenNonces[k];

const action = ['retry_execution', 'exponential_backoff', 'refresh_credentials_then_retry'].includes(req.strategy) ? 'retry' : req.strategy === 'pause_workflow' ? 'pause' : 'notify';
return [{ json: { decision: 'execute', action, req } }];

// Execute Approved Recovery through the n8n public API (allowlisted actions only).
const j = $input.first().json;
const { req, action } = j;
const base = 'http://127.0.0.1:5678/api/v1';
const headers = { 'X-N8N-API-KEY': $env.N8N_PUBLIC_API_KEY, 'content-type': 'application/json' };
const started = Date.now();
async function call(method, path, body) {
  return this.helpers.httpRequest({ method, url: base + path, headers, body, json: true, timeout: 20000, returnFullResponse: true, ignoreHttpStatusErrors: true });
}
let result;
try {
  if (action === 'retry') {
    if (!req.originalExecutionId) throw new Error('no original execution to retry');
    // Retries the failed execution (n8n re-runs from the failed node with original data).
    const r = await call.call(this, 'POST', `/executions/${encodeURIComponent(req.originalExecutionId)}/retry`, { loadWorkflow: true });
    const ok = r.statusCode < 300 && r.body && r.body.status !== 'error';
    result = ok
      ? { status: 'succeeded', executionId: String(r.body.id ?? ''), message: `n8n retry of ${req.originalExecutionId} finished` }
      : { status: 'failed', retryable: r.statusCode >= 500 || r.statusCode === 429, executionId: r.body && r.body.id ? String(r.body.id) : undefined, message: `n8n retry failed (HTTP ${r.statusCode})` };
  } else if (action === 'pause') {
    const r = await call.call(this, 'POST', `/workflows/${encodeURIComponent(req.workflow.externalId)}/deactivate`);
    result = r.statusCode < 300 ? { status: 'succeeded', message: `Workflow ${req.workflow.name} deactivated` } : { status: 'failed', retryable: false, message: `deactivate failed (HTTP ${r.statusCode})` };
  } else {
    if ($env.SLACK_WEBHOOK_URL) {
      await this.helpers.httpRequest({ method: 'POST', url: $env.SLACK_WEBHOOK_URL, body: { text: `Loopmend: INC-${req.incident.number} on ${req.workflow.name} needs an owner fix (${req.incident.category}).` }, json: true });
    }
    result = { status: 'succeeded', message: $env.SLACK_WEBHOOK_URL ? 'Owner notified via Slack' : 'Notification recorded (no Slack webhook configured)' };
  }
} catch (e) {
  result = { status: 'failed', retryable: false, message: String(e.message || e) };
}
result.durationMs = Date.now() - started;
$getWorkflowStaticData('global').processed[req.idempotencyKey] = result;
return [{ json: { status: 200, result } }];
